/* @autogenerated */
package net.civeira.phylax.feature.oauth.client.domain;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

import io.quarkus.runtime.annotations.RegisterForReflection;
import lombok.Builder;
import lombok.Data;
import lombok.NonNull;

/**
 * Client metadata used during OAuth and OIDC flows.
 *
 * Responsibilities: - Provide allowed scopes and grant types for a client. - Describe whether
 * client authentication is required.
 *
 * Design notes: - Immutable value object built via Lombok. - Used by controllers and token
 * builders.
 */
@Data
@Builder
@RegisterForReflection
public class ClientDetails {
  /**
   * Grants of a client without registered grant types: never the password grant (task 0.4).
   */
  public static final List<String> DEFAULT_GRANTS = List.of("authorization_code", "refresh_token");
  /**
   * Response types of a client without registered ones.
   */
  public static final List<String> DEFAULT_RESPONSE_TYPES = List.of("code");
  /**
   * Scopes a client may ask for in user flows when it does not allow all scopes: the standard
   * OpenID Connect ones.
   */
  public static final List<String> OIDC_SCOPES =
      List.of("openid", "profile", "email", "address", "phone", "offline_access");
  private static final String WILDCARD = "*";
  private static final String PASSWORD_GRANT = "password";
  private static final String MFA_GRANT = "mfa";
  private static final String CODE_GRANT = "authorization_code";

  /**
   * Client identifier.
   */
  @NonNull
  private final String clientId;
  /**
   * Scopes allowed for this client.
   */
  @NonNull
  private final List<String> allowedScopes;
  /**
   * Grant types allowed for this client.
   */
  @NonNull
  private final List<String> allowedGrants;

  /**
   * Response types registered for this client (each one a space-separated set, as in RFC 7591).
   */
  @Builder.Default
  @NonNull
  private final List<String> allowedResponseTypes = DEFAULT_RESPONSE_TYPES;

  /**
   * Scopes this client may get for itself with client_credentials. {@code *} means any.
   */
  @Builder.Default
  @NonNull
  private final List<String> clientCredentialsScopes = List.of();

  /**
   * Whether this client must start every authorization request with PAR (RFC 9126 §6).
   */
  private final boolean requirePar;

  /**
   * Algorithm the client signs its request objects with (RFC 9101). Null when not registered.
   */
  private final String requestObjectSigningAlg;

  /**
   * URL of the client's JWKS, for verifying its request objects. Null when not registered.
   */
  private final String jwksUri;

  /**
   * Inline JWKS of the client, for verifying its request objects. Null when not registered.
   */
  private final String jwksJson;

  /**
   * Indicates whether client authentication requires a secret.
   */
  private final boolean protectedWithSecret;

  /**
   * Registered token endpoint auth method. Null when the source does not declare one: then any
   * secret method is accepted.
   */
  private final ClientAuthMethod tokenEndpointAuthMethod;

  /**
   * Indicates whether every authorization code request must include a PKCE code_challenge (S256).
   * Always true for public clients.
   */
  private final boolean requirePkce;

  /**
   * Allowed post-logout redirect URIs for this client. Validated during end-session requests.
   */
  @Builder.Default
  @NonNull
  private final List<String> postLogoutRedirectUris = List.of();

  /** Exact authorization redirects used to authorize RP origins for Session Management. */
  @Builder.Default
  @NonNull
  private final List<String> allowedRedirectUris = List.of();

  /** Registered RP URL receiving a front-channel logout iframe. */
  private final String frontchannelLogoutUri;
  private final boolean frontchannelLogoutSessionRequired;

  /**
   * Resource servers this client may request tokens for, besides itself (task 0.3).
   */
  @Builder.Default
  @NonNull
  private final List<String> allowedAudiences = List.of();

  /**
   * Back-channel logout URI for server-to-server logout notifications. Null when not configured.
   */
  private final String backchannelLogoutUri;

  /**
   * Whether the client requires the {@code sid} claim in the logout token.
   */
  private final boolean backchannelLogoutSessionRequired;

  /**
   * Whether this client is allowed to call the token introspection endpoint.
   */
  private final boolean introspectionAllowed;

  /**
   * Access token TTL in seconds for machine-to-machine flows. Null means fall back to global
   * configuration.
   */
  private final Integer clientCredentialsTokenTtlSeconds;

  /**
   * Algorithm of the client's {@code private_key_jwt} assertions (task 3.2). Null when not
   * registered: then any supported asymmetric one.
   */
  private final String tokenEndpointAuthSigningAlg;

  /**
   * Whether the client gets a pairwise {@code sub} (task 4.4) instead of the public one.
   */
  private final boolean pairwiseSubject;

  /**
   * Registered {@code sector_identifier_uri}: its host is the sector of a pairwise client. Null
   * when not registered: then the host of its only redirect host.
   */
  private final String sectorIdentifierUri;

  /**
   * Whether every access token of the client must be bound to a DPoP key (RFC 9449 §5, task 3.6).
   */
  private final boolean dpopBoundAccessTokens;

  /**
   * Algorithm of signed authorization responses (JARM, task 4.2). Null: the default RS256.
   */
  private final String authorizationSignedResponseAlg;

  /**
   * Algorithm of a signed UserInfo response (task 3.11). Null: plain JSON.
   */
  private final String userinfoSignedResponseAlg;

  /**
   * Key management algorithm to encrypt ID tokens for the client (task 4.5). Null: not encrypted.
   */
  private final String idTokenEncryptedResponseAlg;

  /**
   * Content encryption of ID tokens; with an algorithm and no value, {@code A128CBC-HS256}.
   */
  private final String idTokenEncryptedResponseEnc;

  /**
   * Key management algorithm to encrypt UserInfo for the client (task 4.5). Null: not encrypted.
   */
  private final String userinfoEncryptedResponseAlg;

  /**
   * Content encryption of UserInfo; with an algorithm and no value, {@code A128CBC-HS256}.
   */
  private final String userinfoEncryptedResponseEnc;

  /**
   * {@code authorization_details} types the client may request (RAR, task 4.6).
   */
  @Builder.Default
  @NonNull
  private final List<String> authorizationDetailsTypes = List.of();

  /**
   * Checks that every requested audience is this client or one registered for it.
   *
   * Used by authorize, the token endpoint and device authorization to reject foreign resource
   * servers ({@code invalid_target}, RFC 8707) before authenticating the user.
   *
   * @param audiences requested audiences
   * @return true when all of them are allowed
   */
  public boolean allowsAudiences(List<String> audiences) {
    return audiences == null || audiences.stream()
        .allMatch(aud -> clientId.equals(aud) || allowedAudiences.contains(aud));
  }

  public Optional<String> findBackchannelLogoutUri() {
    return Optional.ofNullable(backchannelLogoutUri).filter(u -> !u.isBlank());
  }

  /**
   * Checks whether a scope is allowed for this client.
   *
   * Returns true when the scope is present in the allowed list. Used to filter requested scopes
   * during token issuance.
   *
   * @param scope scope name
   * @return true when the scope is allowed
   */
  public boolean allowedScope(String scope) {
    return allowedScopes.contains(scope);
  }

  /**
   * Checks whether a grant type is allowed for this client.
   *
   * Returns true when the grant type is present in the allowed list. Used when selecting token
   * granters.
   *
   * @param grant grant type name
   * @return true when the grant is allowed
   */
  public boolean allowedGrant(String grant) {
    // The mfa grant only completes a password grant that asked for a second factor.
    return allowedGrants.contains(grant)
        || MFA_GRANT.equals(grant) && allowedGrants.contains(PASSWORD_GRANT);
  }

  /**
   * Checks whether the client registered a response type.
   *
   * The values are compared as sets of space-separated parts ({@code "id_token code"} equals
   * {@code "code id_token"}), and a response type with {@code code} also needs the
   * authorization_code grant.
   *
   * @param responseType requested response type
   * @return true when it is registered for the client
   */
  public boolean allowsResponseType(String responseType) {
    Set<String> requested = parts(responseType);
    if (requested.isEmpty()) {
      return false;
    }
    if (requested.contains("code") && !allowedGrant(CODE_GRANT)) {
      return false;
    }
    return allowedResponseTypes.stream().map(ClientDetails::parts).anyMatch(requested::equals);
  }

  /**
   * Scopes granted from a user flow request: the requested ones the client may ask for, compared
   * exactly.
   *
   * @param requested requested scopes
   * @return the allowed subset, in request order
   */
  public List<String> grantableScopes(List<String> requested) {
    return allowedScopes.contains(WILDCARD) ? List.copyOf(requested)
        : requested.stream().filter(allowedScopes::contains).toList();
  }

  /**
   * Scopes granted from a user flow request, keeping the ones the login already granted (for
   * example {@code platform:global_access} on the root tenant).
   *
   * @param requested requested scopes
   * @param granted scopes granted by the login, may be null
   * @return the allowed requested scopes followed by the granted ones, without repetitions
   */
  public List<String> grantableScopes(List<String> requested, List<String> granted) {
    Set<String> scopes = new LinkedHashSet<>(grantableScopes(requested));
    if (granted != null) {
      scopes.addAll(granted);
    }
    return List.copyOf(scopes);
  }

  /**
   * Scopes granted to the client itself with client_credentials.
   *
   * Without a requested scope the client gets all of its M2M scopes (RFC 6749 §3.3 default);
   * otherwise only the requested ones it has.
   *
   * @param requested requested scopes
   * @return the granted scopes, possibly empty
   */
  public List<String> m2mScopes(List<String> requested) {
    boolean wildcard = clientCredentialsScopes.contains(WILDCARD);
    if (requested.isEmpty()) {
      return wildcard ? List.of() : List.copyOf(clientCredentialsScopes);
    }
    return wildcard ? List.copyOf(requested)
        : requested.stream().filter(clientCredentialsScopes::contains).toList();
  }

  private static Set<String> parts(String value) {
    return value == null ? Set.of()
        : Arrays.stream(value.trim().split("\\s+")).filter(p -> !p.isBlank())
            .collect(Collectors.toSet());
  }

}
